import { isAxiosError } from 'axios';
import { useCallback } from 'react';
import api from '../api';
import type { SubscriptionStatus } from '../utils/trimClub';
import { upsert } from './useNameList';
import { useApiResource } from './useApiResource';

// Trim Club no painel do admin (planos e assinantes) e na conta do cliente (a assinatura dele),
// com as rotas de /subscriptions (SPEC/2026-11-26-painel-trim-club.md). As ações devolvem o que o
// backend gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type SubscriptionPlan = {
  id: string;
  name: string;
  description: string | null;
  /** O backend serializa o Decimal como texto ("49.90"). */
  monthly_price: string;
  /** null = ilimitado, 0 = não incluso (#16). */
  included_cuts: number | null;
  included_shaves: number | null;
  discount_percentage: string;
  is_active: boolean;
};

/** Campos da criação, já no formato da API. */
export type PlanInput = Pick<
  SubscriptionPlan,
  'name' | 'description' | 'monthly_price' | 'included_cuts' | 'included_shaves' | 'discount_percentage'
>;
/** Alteração parcial: só os campos que mudaram. */
export type PlanChanges = Partial<PlanInput>;

export type Subscription = {
  id: string;
  user_id: string;
  plan_id: string;
  /** "AAAA-MM-DD" */
  start_date: string;
  end_date: string;
  status: SubscriptionStatus;
  plan: SubscriptionPlan;
};

/** Nome e e-mail do assinante; null quando a consulta falhou. */
export type Subscriber = { full_name: string; email: string } | null;

/** Mesma ordem do backend: do plano mais barato para o mais caro. */
const byPrice = (a: SubscriptionPlan, b: SubscriptionPlan) => Number(a.monthly_price) - Number(b.monthly_price);

const loadPlans = async () => (await api.get<SubscriptionPlan[]>('/subscriptions/plans')).data;

export function useAdminPlans() {
  const { data: plans, setData, status, loadError, reload } = useApiResource(
    loadPlans,
    [] as SubscriptionPlan[],
    'Não foi possível carregar os planos.',
  );

  const store = useCallback(
    (saved: SubscriptionPlan) => {
      setData((current) => upsert(current, saved, byPrice));
      return saved;
    },
    [setData],
  );

  const createPlan = useCallback(
    async (input: PlanInput) => store((await api.post<SubscriptionPlan>('/subscriptions/plans', input)).data),
    [store],
  );

  const updatePlan = useCallback(
    async (id: string, changes: PlanChanges) =>
      store((await api.put<SubscriptionPlan>(`/subscriptions/plans/${id}`, changes)).data),
    [store],
  );

  /** O DELETE só desativa: o plano sai da vitrine e desta lista, que só tem os ativos. */
  const removePlan = useCallback(
    async (id: string) => {
      await api.delete(`/subscriptions/plans/${id}`);
      setData((current) => current.filter((p) => p.id !== id));
    },
    [setData],
  );

  return { plans, status, loadError, reload, createPlan, updatePlan, removePlan };
}

type Loaded = { subscriptions: Subscription[]; subscribers: Record<string, Subscriber> };

/** Nome e e-mail de cada assinante. Uma consulta que falha não impede a lista. */
async function loadSubscribers(userIds: string[]): Promise<Record<string, Subscriber>> {
  const unique = [...new Set(userIds)];
  const results = await Promise.allSettled(unique.map((id) => api.get<Subscriber>(`/auth/users/${id}`)));
  return Object.fromEntries(
    unique.map((id, i) => {
      const result = results[i];
      return [id, result.status === 'fulfilled' ? result.value.data : null];
    }),
  );
}

async function loadSubscriptions(): Promise<Loaded> {
  const subscriptions = (await api.get<Subscription[]>('/subscriptions/users')).data;
  return { subscriptions, subscribers: await loadSubscribers(subscriptions.map((s) => s.user_id)) };
}

const NO_SUBSCRIPTIONS: Loaded = { subscriptions: [], subscribers: {} };

export function useSubscriptions() {
  const { data, status, loadError, reload } = useApiResource(
    loadSubscriptions,
    NO_SUBSCRIPTIONS,
    'Não foi possível carregar os assinantes.',
  );
  return { ...data, status, loadError, reload };
}

/** A assinatura do cliente logado, ou null quando ele não tem (404). */
async function loadMine(): Promise<Subscription | null> {
  try {
    return (await api.get<Subscription>('/subscriptions/me')).data;
  } catch (error) {
    if (isAxiosError(error) && error.response?.status === 404) return null;
    throw error;
  }
}

export function useMySubscription() {
  const { data: subscription, setData, status, loadError, reload } = useApiResource(
    loadMine,
    null as Subscription | null,
    'Não foi possível carregar sua assinatura.',
  );

  /** Cancela e passa a mostrar a assinatura como o backend devolveu ("canceled"). */
  const cancel = useCallback(async () => {
    const saved = (await api.put<Subscription>('/subscriptions/me/cancel')).data;
    setData(saved);
    return saved;
  }, [setData]);

  return { subscription, status, loadError, reload, cancel };
}
import React, { useState } from 'react';
import type { PlanChanges, PlanInput, SubscriptionPlan } from '../../hooks/useTrimClub';
import { priceToInput } from '../../utils/serviceValidation';
import {
  parseDiscount,
  parseMonthlyPrice,
  parseQuantity,
  validateDiscount,
  validateMonthlyPrice,
  validatePlanName,
  validateQuantity,
} from '../../utils/trimClub';
import AdminForm, { FormField } from '../AdminForm';
import styles from '../services/Services.module.css';

// Formulário de criação e de edição de um plano do Trim Club (SPEC/2026-11-26-painel-trim-club.md).
// Cortes e barbas inclusos têm a caixa "Ilimitados", que manda null (#16).

/** Quantidade inclusa como está na tela: o número digitado e a caixa "Ilimitados". */
type Quantity = { text: string; unlimited: boolean };

export type PlanFields = {
  name: string;
  description: string;
  price: string;
  cuts: Quantity;
  shaves: Quantity;
  discount: string;
};

type Props = {
  /** Plano em edição. Sem ele, o formulário cria um plano novo. */
  plan?: SubscriptionPlan;
  /** Criação: recebe todos os campos. Edição: só os que mudaram. */
  onSave: (data: PlanInput | PlanChanges) => Promise<unknown>;
  onCancel: () => void;
};

const CUTS_LABEL = 'Cortes inclusos';
const SHAVES_LABEL = 'Barbas inclusas';

const quantityValue = ({ text, unlimited }: Quantity) => (unlimited ? null : (parseQuantity(text) as number));

/** Campos do formulário no formato da API. Só chamar depois de validar. */
export function planInput(fields: PlanFields): PlanInput {
  return {
    name: fields.name.trim(),
    description: fields.description.trim() || null,
    monthly_price: parseMonthlyPrice(fields.price) as string,
    included_cuts: quantityValue(fields.cuts),
    included_shaves: quantityValue(fields.shaves),
    discount_percentage: parseDiscount(fields.discount) as string,
  };
}

/** Campos alterados em relação ao plano salvo. Preço e desconto são comparados pelo valor. */
export function planChanges(plan: SubscriptionPlan, fields: PlanFields): PlanChanges {
  const input = planInput(fields);
  const changes: PlanChanges = {};
  if (input.name !== plan.name) changes.name = input.name;
  if (input.description !== (plan.description || null)) changes.description = input.description;
  if (Number(input.monthly_price) !== Number(plan.monthly_price)) changes.monthly_price = input.monthly_price;
  if (input.included_cuts !== plan.included_cuts) changes.included_cuts = input.included_cuts;
  if (input.included_shaves !== plan.included_shaves) changes.included_shaves = input.included_shaves;
  if (Number(input.discount_percentage) !== Number(plan.discount_percentage)) {
    changes.discount_percentage = input.discount_percentage;
  }
  return changes;
}

const toQuantity = (value: number | null): Quantity =>
  value === null ? { text: '', unlimited: true } : { text: String(value), unlimited: false };

function initialFields(plan?: SubscriptionPlan): PlanFields {
  if (!plan) {
    return { name: '', description: '', price: '', cuts: toQuantity(0), shaves: toQuantity(0), discount: '' };
  }
  return {
    name: plan.name,
    description: plan.description ?? '',
    price: priceToInput(plan.monthly_price),
    cuts: toQuantity(plan.included_cuts),
    shaves: toQuantity(plan.included_shaves),
    discount: Number(plan.discount_percentage) > 0 ? priceToInput(plan.discount_percentage) : '',
  };
}

/** Quantidade inclusa: o número, desligado quando "Ilimitados" está marcada. */
const QuantityField = ({ id, label, value, onChange }: {
  id: string;
  label: string;
  value: Quantity;
  onChange: (value: Quantity) => void;
}) => (
  <>
    <FormField id={id} label={label}>
      <input
        id={id}
        inputMode="numeric"
        value={value.text}
        disabled={value.unlimited}
        onChange={(e) => onChange({ ...value, text: e.target.value })}
      />
    </FormField>
    <label className={styles.check}>
      <input
        type="checkbox"
        aria-label={`${label}: ilimitados`}
        checked={value.unlimited}
        onChange={(e) => onChange({ ...value, unlimited: e.target.checked })}
      />{' '}
      Ilimitados
    </label>
  </>
);

const PlanForm = ({ plan, onSave, onCancel }: Props) => {
  const [fields, setFields] = useState<PlanFields>(() => initialFields(plan));

  const update = <K extends keyof PlanFields>(key: K, value: PlanFields[K]) =>
    setFields((current) => ({ ...current, [key]: value }));
  const set = (key: 'name' | 'description' | 'price' | 'discount') => (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => update(key, event.target.value);

  const validate = () =>
    validatePlanName(fields.name) ??
    validateMonthlyPrice(fields.price) ??
    validateQuantity(fields.cuts.text, fields.cuts.unlimited, CUTS_LABEL) ??
    validateQuantity(fields.shaves.text, fields.shaves.unlimited, SHAVES_LABEL) ??
    validateDiscount(fields.discount);

  const save = async () => {
    const data = plan ? planChanges(plan, fields) : planInput(fields);
    if (Object.keys(data).length === 0) return false;
    await onSave(data);
    return true;
  };

  return (
    <AdminForm
      title={plan ? 'Editar plano' : 'Novo plano'}
      submitLabel="Salvar plano"
      errorFallback="Não foi possível salvar o plano."
      validate={validate}
      save={save}
      onCancel={onCancel}
    >
      <FormField id="plano-nome" label="Nome" wide>
        <input id="plano-nome" value={fields.name} onChange={set('name')} />
      </FormField>

      <FormField id="plano-descricao" label="Descrição (opcional)" wide>
        <textarea id="plano-descricao" rows={2} value={fields.description} onChange={set('description')} />
      </FormField>

      <FormField id="plano-preco" label="Preço mensal (R$)">
        <input id="plano-preco" inputMode="decimal" placeholder="49,90" value={fields.price} onChange={set('price')} />
      </FormField>

      <FormField id="plano-desconto" label="Desconto (%)">
        <input id="plano-desconto" inputMode="decimal" placeholder="0" value={fields.discount} onChange={set('discount')} />
      </FormField>

      <QuantityField id="plano-cortes" label={CUTS_LABEL} value={fields.cuts} onChange={(v) => update('cuts', v)} />
      <QuantityField id="plano-barbas" label={SHAVES_LABEL} value={fields.shaves} onChange={(v) => update('shaves', v)} />
    </AdminForm>
  );
};

export default PlanForm;
import shared from '../../pages/AdminShared.module.css';
import ConfirmButton from '../ConfirmButton';
import type { SubscriptionPlan } from '../../hooks/useTrimClub';
import { formatPrice } from '../../utils/serviceValidation';
import { planBenefitsWithDiscount } from '../../utils/trimClub';
import styles from '../services/Services.module.css';

// Uma linha da tabela de planos do painel (SPEC/2026-11-26-painel-trim-club.md). "Excluir" pede
// confirmação na própria linha; o backend só desativa o plano.

export const DELETE_PLAN_QUESTION = 'Excluir o plano? Ele sai da vitrine, e quem já assina continua com ele.';

type Props = {
  plan: SubscriptionPlan;
  /** Uma ação desta linha está em andamento: os botões ficam desabilitados. */
  busy: boolean;
  onEdit: (plan: SubscriptionPlan) => void;
  onDelete: (plan: SubscriptionPlan) => void;
};

const PlanRow = ({ plan, busy, onEdit, onDelete }: Props) => {
  const benefits = planBenefitsWithDiscount(plan);
  return (
    <tr aria-label={plan.name}>
      <td style={{ color: '#fff', fontWeight: 500 }}>
        {plan.name}
        {plan.description && <span className={styles.description}>{plan.description}</span>}
      </td>
      <td>{formatPrice(plan.monthly_price)}/mês</td>
      <td>{benefits.length ? benefits.join(' · ') : 'Sem benefícios inclusos'}</td>
      <td>
        <ConfirmButton label="Excluir" question={DELETE_PLAN_QUESTION} onConfirm={() => onDelete(plan)} busy={busy}>
          <button className={shared.btnIcon} onClick={() => onEdit(plan)} disabled={busy}>
            Editar
          </button>
        </ConfirmButton>
      </td>
    </tr>
  );
};

export default PlanRow;
import shared from '../../pages/AdminShared.module.css';
import type { Subscriber, Subscription } from '../../hooks/useTrimClub';
import { formatIsoDate } from '../../utils/shopDate';
import { SUBSCRIPTION_STATUS_LABELS } from '../../utils/trimClub';
import { StatusBadge } from '../AdminForm';
import styles from '../services/Services.module.css';

// Assinantes do Trim Club no painel, só de leitura (SPEC/2026-11-26-painel-trim-club.md): o
// cliente, o plano, as datas e a situação, na ordem do backend (a mais nova primeiro).

type Props = {
  subscriptions: Subscription[];
  subscribers: Record<string, Subscriber>;
};

const SubscriptionTable = ({ subscriptions, subscribers }: Props) => {
  if (subscriptions.length === 0) return <p>Nenhum assinante ainda.</p>;
  return (
    <table className={shared.table} aria-label="Assinantes">
      <thead>
        <tr>
          <th>Cliente</th>
          <th>Plano</th>
          <th>Início</th>
          <th>Fim</th>
          <th>Situação</th>
        </tr>
      </thead>
      <tbody>
        {subscriptions.map((sub) => {
          const person = subscribers[sub.user_id];
          const name = person?.full_name ?? 'Cliente não encontrado';
          return (
            <tr key={sub.id} aria-label={name}>
              <td style={{ color: '#fff', fontWeight: 500 }}>
                {name}
                {person && <span className={styles.description}>{person.email}</span>}
              </td>
              <td>{sub.plan.name}</td>
              <td>{formatIsoDate(sub.start_date)}</td>
              <td>{formatIsoDate(sub.end_date)}</td>
              <td>
                <StatusBadge active={sub.status === 'active'} label={SUBSCRIPTION_STATUS_LABELS[sub.status]} />
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
};

export default SubscriptionTable;

