import type { NamedItem, NameListResource } from '../../hooks/useNameList';
import { useRowAction } from '../../hooks/useRowAction';
import NameRow from './NameRow';

// Gestão de uma lista de nomes do painel: criar, renomear e excluir. Usada pelas categorias de
// despesa (SPEC/2026-11-26-painel-despesas.md) e pelas tags da galeria
// (SPEC/2026-11-26-painel-galeria.md). O nome é conferido antes da API; a recusa da API (nome
// repetido) aparece no topo da seção.

type Props<T extends NamedItem> = {
  resource: NameListResource<T>;
  /** Título da seção, no plural ("Categorias"). */
  title: string;
  /**
   * Nome de um item, no singular e feminino ("Categoria", "Tag"): forma o cabeçalho, o campo
   * ("Nova categoria") e as mensagens ("Categoria criada.").
   */
  noun: string;
  deleteQuestion: string;
  /** Confere o nome: a mensagem do problema, ou null. */
  validate: (name: string) => string | null;
  /** O item foi renomeado (com o nome novo) ou excluído (null). */
  onChanged?: (id: string, item: T | null) => void;
};

const NameList = <T extends NamedItem>({ resource, title, noun, deleteQuestion, validate, onChanged }: Props<T>) => {
  const { items, status, loadError, reload, create, rename, remove } = resource;
  const { busyId, message, actionError, run, clear } = useRowAction();
  const [newName, setNewName] = useState('');
  const [invalid, setInvalid] = useState('');
  const lower = noun.toLowerCase();

  /** Confere o nome antes da API. Devolve false (e mostra o erro) quando não serve. */
  const check = (name: string) => {
    clear();
    const problem = validate(name);
    setInvalid(problem ?? '');
    return problem === null;
  };

  const add = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!check(newName)) return;
    if (await run('new', () => create(newName.trim()), `${noun} criada.`)) setNewName('');
  };

  const save = async (item: T, name: string) => {
    if (!check(name)) return false;
    const saved = await run(item.id, () => rename(item.id, name.trim()), `${noun} renomeada.`);
    if (saved) onChanged?.(item.id, saved);
    return saved !== undefined;
  };

  const drop = async (item: T) => {
    setInvalid('');
    const done = await run(item.id, async () => {
      await remove(item.id);
      return true;
    }, `${noun} excluída.`);
    if (done) onChanged?.(item.id, null);
  };

  return (
    <section aria-label={title} style={{ marginTop: '2.5rem' }}>
      <h3 className={shared.title}>{title}</h3>

      <form className={shared.filters} onSubmit={add} noValidate>
        <input aria-label={`Nova ${lower}`} placeholder={`Nova ${lower}`} value={newName} onChange={(e) => setNewName(e.target.value)} />
        <button type="submit" className={shared.btnAction} disabled={status !== 'ready' || busyId === 'new'}>
          Adicionar
        </button>
      </form>

      <ActionFeedback message={message} error={invalid || actionError} />

      <LoadState status={status} loadError={loadError} reload={reload} loadingText={`Carregando ${title.toLowerCase()}...`}>
        {items.length === 0 ? (
          <p>{`Nenhuma ${lower} cadastrada.`}</p>
        ) : (
          <table className={shared.table}>
            <thead>
              <tr>
                <th>{noun}</th>
                <th>Ações</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item) => (
                <NameRow
                  key={item.id}
                  item={item}
                  busy={busyId === item.id}
                  deleteQuestion={deleteQuestion}
                  onRename={save}
                  onDelete={drop}
                />
              ))}
            </tbody>
          </table>
        )}
      </LoadState>
    </section>
  );
};

export default NameList;
import { useState } from 'react';
import shared from '../../pages/AdminShared.module.css';
import ConfirmButton from '../ConfirmButton';
import type { NamedItem } from '../../hooks/useNameList';

// Uma linha da lista de nomes (NameList): "Renomear" troca o nome pelo campo na própria linha;
// "Excluir" pede confirmação.

type Props<T extends NamedItem> = {
  item: T;
  busy: boolean;
  /** Pergunta da confirmação da exclusão. */
  deleteQuestion: string;
  /** Grava o nome novo. Devolve true quando gravou, para a linha sair da edição. */
  onRename: (item: T, name: string) => Promise<boolean>;
  onDelete: (item: T) => void;
};

const NameRow = <T extends NamedItem>({ item, busy, deleteQuestion, onRename, onDelete }: Props<T>) => {
  // null: fora da edição.
  const [name, setName] = useState<string | null>(null);

  const save = async () => {
    if (name !== null && (await onRename(item, name))) setName(null);
  };

  if (name !== null) {
    return (
      <tr aria-label={item.name}>
        <td>
          <input aria-label={`Novo nome de ${item.name}`} value={name} onChange={(e) => setName(e.target.value)} />
        </td>
        <td>
          <button className={shared.btnIcon} onClick={save} disabled={busy}>Salvar</button>
          <button className={shared.btnIcon} onClick={() => setName(null)} disabled={busy}>Cancelar</button>
        </td>
      </tr>
    );
  }

  return (
    <tr aria-label={item.name}>
      <td style={{ color: '#fff', fontWeight: 500 }}>{item.name}</td>
      <td>
        <ConfirmButton label="Excluir" question={deleteQuestion} onConfirm={() => onDelete(item)} busy={busy}>
          <button className={shared.btnIcon} onClick={() => setName(item.name)} disabled={busy}>
            Renomear
          </button>
        </ConfirmButton>
      </td>
    </tr>
  );
};

export default NameRow;
import { useCallback } from 'react';
import api from '../api';
import { useApiResource } from './useApiResource';

// Lista de nomes do painel (categorias de despesa e tags da galeria): carrega de `path`, cria
// com POST, renomeia com PUT `path/{id}` e apaga com DELETE, mantendo a ordem alfabética do
// backend (SPEC/2026-11-26-painel-despesas.md e SPEC/2026-11-26-painel-galeria.md). As ações
// devolvem o que o backend gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type NamedItem = { id: string; name: string };

export const byName = (a: NamedItem, b: NamedItem) => a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' });

/** Põe `saved` na lista, no lugar do item de mesmo id ou como novo, e ordena. */
export function upsert<T extends { id: string }>(list: T[], saved: T, order: (a: T, b: T) => number): T[] {
  return [...list.filter((item) => item.id !== saved.id), saved].sort(order);
}

export function useNameList<T extends NamedItem>(path: string, loadErrorText: string) {
  const load = useCallback(async () => (await api.get<T[]>(path)).data, [path]);
  const { data: items, setData, status, loadError, reload } = useApiResource(load, [] as T[], loadErrorText);

  const store = useCallback((saved: T) => {
    setData((current) => upsert(current, saved, byName));
    return saved;
  }, []);

  const create = useCallback(async (name: string) => store((await api.post<T>(path, { name })).data), [path, store]);

  const rename = useCallback(
    async (id: string, name: string) => store((await api.put<T>(`${path}/${id}`, { name })).data),
    [path, store],
  );

  const remove = useCallback(
    async (id: string) => {
      await api.delete(`${path}/${id}`);
      setData((current) => current.filter((item) => item.id !== id));
    },
    [path],
  );

  return { items, status, loadError, reload, create, rename, remove };
}

export type NameListResource<T extends NamedItem> = ReturnType<typeof useNameList<T>>;
