import { useCallback, useEffect, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Carga de dados da API com "carregando", erro em português e "Tentar de novo". Usado pelo
// painel de serviços (SPEC/2026-11-23-painel-servicos.md) e por Meus agendamentos
// (SPEC/2026-11-25-meus-agendamentos.md). `setData` deixa quem usa atualizar a lista depois
// de uma ação, sem carregar de novo. `load` precisa ser estável (função do módulo ou
// useCallback): uma função nova a cada renderização carregaria de novo a cada renderização.

export type LoadStatus = 'loading' | 'ready' | 'error';

export function useApiResource<T>(load: () => Promise<T>, initial: T, fallbackError: string) {
  const [data, setData] = useState<T>(initial);
  const [status, setStatus] = useState<LoadStatus>('loading');
  const [loadError, setLoadError] = useState('');
  // Mudar o número pede uma nova carga ("Tentar de novo").
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setStatus('loading');
    load()
      .then((loaded) => {
        if (!active) return;
        setData(loaded);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        setLoadError(apiErrorMessage(error, fallbackError));
        setStatus('error');
      });
    return () => {
      active = false;
    };
  }, [attempt, load, fallbackError]);

  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  return { data, setData, status, loadError, reload };
}
import { useCallback, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Ação sobre uma linha de uma tabela do painel: a linha fica ocupada enquanto a ação roda, e o
// resultado aparece no topo, como mensagem ou erro da API. Usado pelos painéis de serviços
// (SPEC/2026-11-23-painel-servicos.md) e de usuários (SPEC/2026-11-25-admin-usuarios.md).

export function useRowAction() {
  const [busyId, setBusyId] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');

  const clear = useCallback(() => {
    setMessage('');
    setActionError('');
  }, []);

  /** Roda `action` com a linha `id` ocupada. Devolve o resultado, ou undefined se falhou. */
  const run = useCallback(
    async <T,>(id: string, action: () => Promise<T>, done: string): Promise<T | undefined> => {
      clear();
      setBusyId(id);
      try {
        const result = await action();
        setMessage(done);
        return result;
      } catch (error) {
        setActionError(apiErrorMessage(error, 'Não foi possível concluir a ação.'));
        return undefined;
      } finally {
        setBusyId(null);
      }
    },
    [clear],
  );

  return { busyId, message, actionError, run, clear, setMessage };
}
import React, { useState, type ReactNode } from 'react';
import { apiErrorMessage } from '../utils/apiError';
import styles from './services/Services.module.css';

// Moldura dos formulários do painel do admin: título, erro, "Nada mudou.", "Salvando..." e
// "Cancelar". Usada pelos formulários de serviço (SPEC/2026-11-23-painel-servicos.md) e de
// barbeiro (SPEC/2026-11-26-painel-barbeiros.md). Quem usa cuida só dos campos.

type Props = {
  title: string;
  /** Texto do botão de salvar. Enquanto salva, vira "Salvando...". */
  submitLabel: string;
  /** Mensagem quando a API falha sem dizer o motivo. */
  errorFallback: string;
  /** Confere os campos antes da API: a mensagem do problema, ou null. */
  validate: () => string | null;
  /**
   * Grava. Devolve false quando não havia nada para gravar (o formulário diz "Nada mudou.").
   * Quem chamou fecha o formulário depois de salvar.
   */
  save: () => Promise<boolean>;
  onCancel: () => void;
  children: ReactNode;
};

const AdminForm = ({ title, submitLabel, errorFallback, validate, save, onCancel, children }: Props) => {
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setInfo('');

    const problem = validate();
    if (problem) {
      setError(problem);
      return;
    }

    setSaving(true);
    try {
      if (!(await save())) {
        setInfo('Nada mudou.');
        setSaving(false);
      }
    } catch (err) {
      setError(apiErrorMessage(err, errorFallback));
      setSaving(false);
    }
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit} noValidate aria-label={title}>
      <h3>{title}</h3>

      {children}

      {error && <p className={styles.error} role="alert">{error}</p>}
      {info && <p className={styles.info} role="status">{info}</p>}

      <div className={styles.actions}>
        <button type="button" className={styles.secondary} onClick={onCancel} disabled={saving}>
          Cancelar
        </button>
        <button type="submit" className={styles.primary} disabled={saving}>
          {saving ? 'Salvando...' : submitLabel}
        </button>
      </div>
    </form>
  );
};

/** Um campo do formulário: rótulo e controle, em meia linha ou na linha inteira (`wide`). */
export const FormField = ({ id, label, wide = false, children }: {
  id: string;
  label: string;
  wide?: boolean;
  children: ReactNode;
}) => (
  <div className={wide ? `${styles.field} ${styles.wide}` : styles.field}>
    <label htmlFor={id}>{label}</label>
    {children}
  </div>
);

/**
 * Selo de situação das linhas do painel: "Ativo" ou "Desativado", ou `label` com a cor de
 * `active` (a situação da assinatura, SPEC/2026-11-26-painel-trim-club.md).
 */
export const StatusBadge = ({ active, label }: { active: boolean; label?: string }) => (
  <span className={`${styles.badge} ${active ? styles.badgeActive : styles.badgeInactive}`}>
    {label ?? (active ? 'Ativo' : 'Desativado')}
  </span>
);

export default AdminForm;
import { useState, type ReactNode } from 'react';
import shared from '../pages/AdminShared.module.css';

// Ação destrutiva com confirmação no próprio lugar: o botão vira a pergunta, "Confirmar" e
// "Voltar". Usado em "Desativar" serviço (SPEC/2026-11-23-painel-servicos.md) e em "Cancelar"
// agendamento (SPEC/2026-11-25-meus-agendamentos.md).

type Props = {
  /** Texto do botão que abre a confirmação. */
  label: string;
  /** Nome acessível do botão, quando o texto sozinho não basta (vários na mesma tela). */
  ariaLabel?: string;
  /** Pergunta mostrada no lugar do botão. */
  question: string;
  onConfirm: () => void;
  /** Uma ação está em andamento: os botões ficam desabilitados. */
  busy?: boolean;
  /** Outras ações, mostradas ao lado do botão e escondidas durante a confirmação. */
  children?: ReactNode;
};

const ConfirmButton = ({ label, ariaLabel, question, onConfirm, busy = false, children }: Props) => {
  const [confirming, setConfirming] = useState(false);

  if (confirming) {
    return (
      <>
        <span className={shared.confirmQuestion}>{question}</span>
        <button
          type="button"
          className={`${shared.btnIcon} ${shared.btnDanger}`}
          onClick={() => {
            setConfirming(false);
            onConfirm();
          }}
          disabled={busy}
        >
          Confirmar
        </button>
        <button type="button" className={shared.btnIcon} onClick={() => setConfirming(false)} disabled={busy}>
          Voltar
        </button>
      </>
    );
  }

  return (
    <>
      {children}
      <button
        type="button"
        className={`${shared.btnIcon} ${shared.btnDanger}`}
        aria-label={ariaLabel}
        onClick={() => setConfirming(true)}
        disabled={busy}
      >
        {label}
      </button>
    </>
  );
};

export default ConfirmButton;
import type { ReactNode } from 'react';
import type { LoadStatus } from '../hooks/useApiResource';
import shared from '../pages/AdminShared.module.css';
import styles from './services/Services.module.css';

// Estado da carga de uma tela do painel (useApiResource): "carregando", o erro com "Tentar de
// novo", ou o conteúdo. E as mensagens do resultado de uma ação (useRowAction). Usado pelos
// painéis de serviços e de usuários (SPEC/2026-11-25-admin-usuarios.md).

type Props = {
  status: LoadStatus;
  loadError: string;
  reload: () => void;
  /** Texto enquanto carrega. */
  loadingText: string;
  children: ReactNode;
};

const LoadState = ({ status, loadError, reload, loadingText, children }: Props) => {
  if (status === 'loading') return <p>{loadingText}</p>;
  if (status === 'error') {
    return (
      <div>
        <p className={styles.error} role="alert">{loadError}</p>
        <button type="button" className={shared.btnAction} onClick={reload}>Tentar de novo</button>
      </div>
    );
  }
  return <>{children}</>;
};

/** Mensagem de sucesso e erro de uma ação, no topo da tela. */
export const ActionFeedback = ({ message, error }: { message: string; error: string }) => (
  <>
    {message && <p className={styles.info} role="status">{message}</p>}
