import { useState, type ReactNode } from 'react';
import shared from '../../pages/AdminShared.module.css';
import { validateReason } from '../../utils/galleryValidation';

// "Recusar" de uma foto pendente (SPEC/2026-11-26-painel-galeria.md): abre, na linha, o campo do
// motivo com "Confirmar recusa" e "Voltar". O motivo é conferido antes da API e vai aparado.

type Props = {
  busy: boolean;
  /** Recusa com o motivo. Devolve true quando deu certo, para o campo fechar. */
  onReject: (reason: string) => Promise<boolean>;
  /** Outras ações, escondidas enquanto o motivo é pedido. */
  children?: ReactNode;
};

const RejectButton = ({ busy, onReject, children }: Props) => {
  // null: fechado.
  const [reason, setReason] = useState<string | null>(null);
  const [invalid, setInvalid] = useState('');

  const confirm = async () => {
    const problem = validateReason(reason ?? '');
    setInvalid(problem ?? '');
    if (!problem && (await onReject((reason ?? '').trim()))) setReason(null);
  };

  if (reason === null) {
    return (
      <>
        {children}
        <button type="button" className={`${shared.btnIcon} ${shared.btnDanger}`} onClick={() => setReason('')} disabled={busy}>
          Recusar
        </button>
      </>
    );
  }

  return (
    <>
      <input aria-label="Motivo da recusa" placeholder="Motivo da recusa" value={reason} onChange={(e) => setReason(e.target.value)} />
      <button type="button" className={`${shared.btnIcon} ${shared.btnDanger}`} onClick={confirm} disabled={busy}>
        Confirmar recusa
      </button>
      <button
        type="button"
        className={shared.btnIcon}
        onClick={() => {
          setReason(null);
          setInvalid('');
        }}
        disabled={busy}
      >
        Voltar
      </button>
      {invalid && <span className={shared.confirmQuestion} role="alert">{invalid}</span>}
    </>
  );
};

export default RejectButton;
// Regras de texto comuns aos formulários do painel.

/** Texto com 1 a `max` caracteres, sem contar os espaços das pontas (o backend apara). */
export const fitsTrimmed = (text: string, max: number) => {
  const length = text.trim().length;
  return length >= 1 && length <= max;
};
import { fitsTrimmed } from './textValidation';

// Validação dos campos da galeria no painel, com as regras do backend
// (src/backend/modules/gallery/schemas.py; SPEC/2026-11-26-painel-galeria.md).
// Cada validate* devolve a mensagem de erro, ou null quando o valor serve.

export const IMAGE_URL_MAX = 1000;
export const PHOTO_DESCRIPTION_MAX = 500;
export const REASON_MAX = 500;
export const TAG_NAME_MAX = 50;

export const IMAGE_URL_ERROR = 'Informe a URL da imagem (http ou https, até 1.000 caracteres)';
export const PHOTO_DESCRIPTION_ERROR = `Descrição deve ter até ${PHOTO_DESCRIPTION_MAX} caracteres`;
export const BARBER_ERROR = 'Escolha o barbeiro da foto';
export const REASON_ERROR = `O motivo deve ter entre 1 e ${REASON_MAX} caracteres`;
export const TAG_NAME_ERROR = `Nome da tag deve ter entre 1 e ${TAG_NAME_MAX} caracteres`;

/** URL http(s) sem espaços, até o tamanho da coluna. */
export function validateImageUrl(text: string): string | null {
  const url = text.trim();
  return /^https?:\/\/\S+$/i.test(url) && url.length <= IMAGE_URL_MAX ? null : IMAGE_URL_ERROR;
}

/** A descrição é opcional: vazia serve. */
export function validatePhotoDescription(text: string): string | null {
  return text.trim().length <= PHOTO_DESCRIPTION_MAX ? null : PHOTO_DESCRIPTION_ERROR;
}

export function validateReason(text: string): string | null {
  return fitsTrimmed(text, REASON_MAX) ? null : REASON_ERROR;
}

export function validateTagName(text: string): string | null {
  return fitsTrimmed(text, TAG_NAME_MAX) ? null : TAG_NAME_ERROR;
}
