export function parseMonthlyPrice(text: string): string | null {
  const price = parsePrice(text);
  return price !== null && Number(price) > 0 ? price : null;
}

export function validateMonthlyPrice(text: string): string | null {
  return parseMonthlyPrice(text) === null ? MONTHLY_PRICE_ERROR : null;
}

/** Quantidade inclusa: inteiro de 0 a 999, ou null quando não serve. */
export function parseQuantity(text: string): number | null {
  const value = text.trim();
  if (!/^\d+$/.test(value)) return null;
  const quantity = Number(value);
  return quantity <= QUANTITY_MAX ? quantity : null;
}

/** Ilimitado dispensa a quantidade. */
export function validateQuantity(text: string, unlimited: boolean, label: string): string | null {
  return unlimited || parseQuantity(text) !== null ? null : quantityError(label);
}

/** Desconto no formato da API ("10.00"); vazio é zero. null quando passa de 100. */
export function parseDiscount(text: string): string | null {
  if (!text.trim()) return '0.00';
  const discount = parsePrice(text);
  return discount !== null && Number(discount) <= 100 ? discount : null;
}

export function validateDiscount(text: string): string | null {
  return parseDiscount(text) === null ? DISCOUNT_ERROR : null;
}
// Validação e conversão dos campos do formulário de serviço do painel, com as regras do
// backend (src/backend/modules/services/schemas.py; SPEC/2026-11-23-painel-servicos.md).
// Cada validate* devolve a mensagem de erro, ou null quando o valor serve.

export const NAME_MIN = 2;
export const NAME_MAX = 100;
export const DURATION_MAX = 720;
/** Dígitos da parte inteira que cabem no Numeric(10, 2) da coluna: até 99.999.999. */
const PRICE_INT_DIGITS = 8;

// Só dígitos, com um separador decimal (vírgula ou ponto) e até 2 casas. Sem milhar.
const PRICE_FORMAT = /^(\d+)(?:[.,](\d{1,2}))?$/;

export const NAME_ERROR = `Nome deve ter entre ${NAME_MIN} e ${NAME_MAX} caracteres`;
export const PRICE_ERROR = 'Preço deve ser um valor entre 0 e 99.999.999,99, com até 2 casas decimais';
export const DURATION_ERROR = `Duração deve ser um número inteiro de 1 a ${DURATION_MAX} minutos`;

export function validateServiceName(name: string): string | null {
  const length = name.trim().length;
  return length < NAME_MIN || length > NAME_MAX ? NAME_ERROR : null;
}

/**
 * Preço digitado ("35", "35,5", "35.50") no formato da API, com 2 casas ("35.50"),
 * ou null quando não serve. Converte o texto sem passar por float, para não arredondar.
 */
export function parsePrice(text: string): string | null {
  const match = PRICE_FORMAT.exec(text.trim());
  if (!match) return null;
  const integer = match[1].replace(/^0+(?=\d)/, '');
  if (integer.length > PRICE_INT_DIGITS) return null;
  return `${integer}.${(match[2] ?? '').padEnd(2, '0')}`;
}

export function validatePrice(text: string): string | null {
  return parsePrice(text) === null ? PRICE_ERROR : null;
}

/** Duração digitada como inteiro, ou null quando não é um inteiro de 1 a 720. */
export function parseDuration(text: string): number | null {
  const value = text.trim();
  if (!/^\d+$/.test(value)) return null;
  const minutes = Number(value);
  return minutes >= 1 && minutes <= DURATION_MAX ? minutes : null;
}

export function validateDuration(text: string): string | null {
  return parseDuration(text) === null ? DURATION_ERROR : null;
}

/** Preço da API ("35.00" ou 35) para mostrar no campo do formulário ("35,00"). */
export function priceToInput(price: string | number): string {
  return Number(price).toFixed(2).replace('.', ',');
}

/** Preço da API para a tabela, em reais ("R$ 35,00"). */
export function formatPrice(price: string | number): string {
  return Number(price).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}
// Datas do agendamento no fuso da barbearia (SPEC/2026-11-18-agendamento-fuso-horario.md).
// Datas são strings "AAAA-MM-DD"; o backend lê horários sem fuso no fuso da barbearia.

export const SHOP_TIMEZONE = 'America/Sao_Paulo';
export const MAX_DAYS_AHEAD = 30;

const parse = (isoDate: string): [number, number, number] => {
  const [year, month, day] = isoDate.split('-').map(Number);
  return [year, month, day];
};

/** "Hoje" no fuso da barbearia, e não em UTC como `toISOString()`. */
export function shopToday(now: Date = new Date(), timeZone: string = SHOP_TIMEZONE): string {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(now);
}

export function addDays(isoDate: string, days: number): string {
  const [year, month, day] = parse(isoDate);
  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
}

/** "segunda-feira, 09/11/2026" */
export function formatLongDate(isoDate: string): string {
  const [year, month, day] = parse(isoDate);
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'UTC',
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(new Date(Date.UTC(year, month - 1, day, 12)));
}

/** Valor de `start_datetime` enviado à API: sem fuso, lido no fuso da barbearia. */
export function toStartDatetime(isoDate: string, time: string): string {
  return `${isoDate}T${time}:00`;
}

/** Data e hora de um instante da API no fuso da barbearia: "qua., 02/12/2026 às 10:00". */
export function formatShopDateTime(iso: string, timeZone: string = SHOP_TIMEZONE): string {
  const parts = new Intl.DateTimeFormat('pt-BR', {
    timeZone,
    weekday: 'short',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(iso));
  const part = (type: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === type)?.value ?? '';
  return `${part('weekday')}, ${part('day')}/${part('month')}/${part('year')} às ${part('hour')}:${part('minute')}`;
}

/** Dia de um instante da API no fuso da barbearia: "26/11/2026". */
import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios';

// Erros da API como o axios os entrega, para os testes dos componentes e hooks.

/** Resposta de erro com o `detail` do FastAPI (texto, ou lista de { msg } no 422). */
export function httpError(status: number, detail?: unknown): AxiosError {
  const config = { headers: {} } as InternalAxiosRequestConfig;
  const data = detail === undefined ? {} : { detail };
  const response = { status, data, statusText: '', headers: {}, config } as AxiosResponse;
  return new AxiosError(`HTTP ${status}`, AxiosError.ERR_BAD_REQUEST, config, null, response);
}

/** Falha sem resposta, como a de rede fora do ar. */
export function networkError(): AxiosError {
  return new AxiosError('Network Error', AxiosError.ERR_NETWORK, { headers: {} } as InternalAxiosRequestConfig);
}
import { isAxiosError } from 'axios';

type ValidationIssue = { msg?: string };

/**
 * Mensagem em português para mostrar ao usuário a partir de um erro da API.
 * O 422 do FastAPI traz uma lista de problemas ({ msg }), com o prefixo "Value error, "
 * nas validações escritas no backend; os outros erros trazem `detail` como texto.
 */
export function apiErrorMessage(error: unknown, fallback = 'Não foi possível concluir. Tente de novo.'): string {
  if (!isAxiosError(error)) return fallback;
  if (!error.response) return 'Sem conexão com o servidor. Verifique a internet e tente de novo.';
  const detail = (error.response.data as { detail?: unknown } | undefined)?.detail;
  if (typeof detail === 'string' && detail) return detail;
  if (Array.isArray(detail)) {
    const messages = detail
      .map((issue: ValidationIssue) => (issue?.msg ?? '').replace(/^Value error, /, ''))
      .filter(Boolean);
    if (messages.length) return messages.join(' | ');
  }
  return fallback;
}

